mapper.select:

		SELECT * FROM quiz
    	ORDER BY quiz_id DESC
    	LIMIT #{limit}
    	OFFSET #{offset}

SELECT quiz_region_tags_id, tag_name, region_id, quiz_id
FROM quiz_region_tags 
WHERE quiz_id = #{quizId}


SELECT DISTINCT q.*
FROM regions r JOIN quiz_region_tags qrt ON r.region_id =
qrt.region_id JOIN quiz q
ON qrt.quiz_id = q.quiz_id 

		r.sido_code = #{sidoCode}


		AND r.gugun_code = #{gugunCode}
